/*
 * A075422  Primitive numbers n such that the product of factorials of all
 *          proper divisors of n does not divide n!.
 * https://oeis.org/A075422
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   * a(n) = n-th primitive number such that the product of the
 *            factorials * of all proper divisors of the number does not
 *            divide the * factorial of the number. * The sequence is
 *            generated by scanning integers in increasing order, * testing
 *            the divisibility condition, and keeping only those numbers t...
 * Range:     u8 n <= 19, u16 n <= 53, u32 n <= 53, u64 n <= 53, u128 n <= 53,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdbool.h>
#include <stdlib.h>

/* ----------------------------------------------------------------------
 *  Global parameters
 * ---------------------------------------------------------------------- */
#define MAX_CANDIDATE  1000000   /* adequate upper bound for first 10 000 terms */
#define MAX_DIVISORS   500        /* max number of divisors for any n <= MAX_CANDIDATE */
#define MAX_PRIMES     16        /* max distinct prime factors for any n <= MAX_CANDIDATE */

/* ----------------------------------------------------------------------
 *  Least prime factor array
 * ---------------------------------------------------------------------- */
static int spf[MAX_CANDIDATE + 1];

/* ----------------------------------------------------------------------
 *  Initialise spf array with a linear sieve
 * ---------------------------------------------------------------------- */
static void init_spf(void)
{
    for (int i = 0; i <= MAX_CANDIDATE; ++i) spf[i] = i;
    for (int i = 2; i * i <= MAX_CANDIDATE; ++i)
        if (spf[i] == i)
            for (int j = i * i; j <= MAX_CANDIDATE; j += i)
                if (spf[j] == j) spf[j] = i;
}

/* ----------------------------------------------------------------------
 *  Legendre exponent of prime p in n!
 * ---------------------------------------------------------------------- */
static inline int legendre_exp(int n, int p)
{
    int exp = 0;
    while (n) {
        n /= p;
        exp += n;
    }
    return exp;
}

/* ----------------------------------------------------------------------
 *  Factorise n into arrays primes[], exps[] (size <= MAX_PRIMES)
 * ---------------------------------------------------------------------- */
static void factorise(int n, int *primes, int *exps, int *cnt)
{
    int c = 0;
    while (n > 1) {
        int p = spf[n];
        int e = 0;
        while (n % p == 0) {
            n /= p;
            ++e;
        }
        primes[c] = p;
        exps[c] = e;
        ++c;
    }
    *cnt = c;
}

/* ----------------------------------------------------------------------
 *  Recursive divisor generation
 * ---------------------------------------------------------------------- */
static void gen_divs_rec(int idx, int cur,
                        const int *primes, const int *exps,
                        int parts, int *divs, int *div_cnt)
{
    if (idx == parts) {
        divs[(*div_cnt)++] = cur;
        return;
    }
    int p = primes[idx];
    int e_max = exps[idx];
    int val = 1;
    for (int e = 0; e <= e_max; ++e) {
        gen_divs_rec(idx + 1, cur * val,
                     primes, exps, parts, divs, div_cnt);
        val *= p;
    }
}

/* ----------------------------------------------------------------------
 *  Test whether n satisfies the "fails factorial divisibility" condition
 * ---------------------------------------------------------------------- */
static bool test_candidate(int n)
{
    int primes[MAX_PRIMES], exps[MAX_PRIMES], fac_cnt;
    factorise(n, primes, exps, &fac_cnt);

    int divs[MAX_DIVISORS], div_cnt = 0;
    gen_divs_rec(0, 1, primes, exps, fac_cnt, divs, &div_cnt);

    /* for each prime dividing n check the inequality */
    for (int pi = 0; pi < fac_cnt; ++pi) {
        int p = primes[pi];
        int vp_n = legendre_exp(n, p);
        int sum = 0;
        for (int di = 0; di < div_cnt; ++di) {
            int d = divs[di];
            if (d == n) continue;           /* exclude n itself */
            sum += legendre_exp(d, p);
            if (sum > vp_n) return true;    /* condition satisfied */
        }
    }
    return false;                          /* condition not satisfied */
}

/* ----------------------------------------------------------------------
 *  Memoised sequence generation
 * ---------------------------------------------------------------------- */
seq_t a(idx_t n)
{
    static seq_t *seq = NULL;          /* stored primitive numbers */
    static size_t seq_len = 0, seq_cap = 0;
    static int  *primitives = NULL;    /* same as seq but as int for divisibility test */
    static size_t prim_len = 0, prim_cap = 0;
    static int candidate = 2;          /* next integer to test */

    /* initialise data structures once */
    if (seq == NULL) {
        init_spf();
        seq_cap = 256;
        seq = (seq_t*)malloc(seq_cap * sizeof(seq_t));
        primitives = (int*)malloc(seq_cap * sizeof(int));
    }

    /* extend sequence until we have enough terms */
    while (seq_len < n) {
        if (candidate <= MAX_CANDIDATE) {
            if (test_candidate(candidate)) {
                /* check primitive condition: not divisible by any existing primitive */
                bool divisible = false;
                for (size_t i = 0; i < prim_len && primitives[i] <= candidate / 2; ++i) {
                    if (candidate % primitives[i] == 0) { divisible = true; break; }
                }
                if (!divisible) {
                    /* append to sequence */
                    if (seq_len == seq_cap) {
                        seq_cap *= 2;
                        seq = (seq_t*)realloc(seq, seq_cap * sizeof(seq_t));
                        primitives = (int*)realloc(primitives, seq_cap * sizeof(int));
                    }
                    seq[seq_len] = (seq_t)candidate;
                    primitives[prim_len] = candidate;
                    ++seq_len;
                    ++prim_len;
                }
            }
        } else {
            /* Should not happen for requested limits; bail out if limit exceeded */
            break;
        }
        ++candidate;
    }

    return seq[n - 1];   /* indices are 1-based */
}
